const r2 = v => Math.round(v * 100) / 100;
function rng(seed) { let s = seed; return () => (s = (s * 16807) % 2147483647) / 2147483647; }
const lg = (id, stops, attrs = '') => `<linearGradient id="__ID__${id}" ${attrs}>${stops.map(([o, c, op]) => `<stop offset="${o}" stop-color="${c}"${op === undefined ? '' : ` stop-opacity="${op}"`}/>`).join('')}</linearGradient>`;

