const ice = (x, y, a = 0, w = 25, h = 25, edge = '#9fb6aa') => `<g transform="translate(${x} ${y}) rotate(${a})"><rect width="${w}" height="${h}" rx="4" fill="${ref('ice')}" stroke="${edge}" stroke-opacity=".55" stroke-width=".9"/><path d="M4 ${h - 4}V7Q4 4 7 4h${w - 13}" fill="none" stroke="#fff" stroke-opacity=".8" stroke-width="1.3"/><path d="m5 ${h - 3} ${w - 9}-2" fill="none" stroke="#7f988b" stroke-opacity=".35" stroke-width=".7"/></g>`;
const wedge = (x, y, r = 20, a = 0) => `<g transform="translate(${x} ${y}) rotate(${a})"><path d="M${-r} 0A${r} ${r} 0 0 0 ${r} 0Z" fill="#3f7a22"/><path d="M${-r + 2.2} 0A${r - 2.2} ${r - 2.2} 0 0 0 ${r - 2.2} 0Z" fill="#e6efb4"/><path d="M${-r + 4} 1A${r - 4} ${r - 4} 0 0 0 ${r - 4} 1Z" fill="#b5d067"/><path d="M${-r + 4} 1A${r - 4} ${r - 4} 0 0 0 0 ${r - 3}L0 1Z" fill="#9dbd4c" opacity=".55"/>${[1, 2, 3, 4, 5].map(i => { const t = i * Math.PI / 6; return `<path d="M0 1 ${r2(Math.cos(t) * (r - 4))} ${r2(Math.sin(t) * (r - 4) + 1)}" stroke="#f1f6cf" stroke-width=".8"/>`; }).join('')}</g>`;
const mint = (x, y, s = 1, a = 0) => `<g transform="translate(${x} ${y}) rotate(${a}) scale(${s})"><path d="M0 0C-14-5-19-16-12-28 3-24 8-12 0 0Z" fill="${ref('mint')}" stroke="#2f5e22" stroke-width=".7"/><path d="M0 0-11-25m4 15-7-4m5-2 5-6" fill="none" stroke="#cfe08a" stroke-width=".8"/></g>`;
