  const defs = lg('milk', [[0, '#b99c74'], [.1, '#d9c6a6'], [.26, '#f3e9d6'], [.36, '#fcf8ef'], [.46, '#efe3cd'], [.75, '#dfcdae'], [.92, '#c9b08a'], [1, '#b39670']])
